const COLORS = { R: '赤', B: '青', G: '緑', Y: '黄', P: '紫', E: '' };
const ALL = [...RED, ...BLUE, ...GREEN, ...YELLOW, ...PURPLE, ...ENCH].map(L).map(c => ({ ...c, color: COLORS[c.id[0]], category: c.id[0] === 'E' ? 'エンチャント' : 'キャラクター' }));
