const TUNED = (() => { try { return process.env.VB_DESIGN_RAW ? {} : JSON.parse(require('node:fs').readFileSync(require('node:path').join(__dirname, 'claude_1024c', 'tuned.json'), 'utf8')); } catch (_) { return {}; } })();
